static void ctrl_task_path_status_log(uint8 task_id,
                                      const char *event,
                                      uint8 sd_result,
                                      uint8 flash_result,
                                      uint8 flash_load_result)
{
    nav_ins_state_t ins_state;

    if (data_logger_is_busy() != 0U)
    {
        printf("[NAV_PATH] task%u status skipped while logger busy: %s\r\n",
               (unsigned)task_id,
               (event != NULL) ? event : "");
        return;
    }

    nav_ins_get_state(&ins_state);
    (void)nav_control_path_append_status_to_sd(task_id,
                                               event,
                                               sd_result,
                                               flash_result,
                                               flash_load_result,
                                               IMU_AHRS_IsReferenceReady(),
                                               ins_state.valid,
                                               data_logger_get_state(),
                                               data_logger_get_last_error(),
                                               data_logger_get_task_id(),
                                               data_logger_get_profile(),
                                               data_logger_get_target_src());
}

static int16 ctrl_pwm_test_clip_duty(int16 duty)
{
    if (duty > CTRL_PWM_TEST_DUTY_MAX)
    {
        duty = CTRL_PWM_TEST_DUTY_MAX;
    }
    else if (duty < CTRL_PWM_TEST_DUTY_MIN)
    {
        duty = CTRL_PWM_TEST_DUTY_MIN;
    }

    return duty;
}

static float ctrl_clip_f32(float value, float low, float high)
{
    if (value > high)
    {
        return high;
    }
    if (value < low)
    {
        return low;
    }

    return value;
}

static float ctrl_abs_f32(float value)
{
    return (value >= 0.0f) ? value : -value;
}

static float ctrl_task1_wrap180(float angle_deg)
{
    while (angle_deg > 180.0f)
    {
        angle_deg -= 360.0f;
    }
    while (angle_deg <= -180.0f)
    {
        angle_deg += 360.0f;
    }

    return angle_deg;
}

static uint32 ctrl_scan_elapsed_ms(uint32 now_ms, uint32 start_ms)
{
    return now_ms - start_ms;
}

static uint8 ctrl_steer_feedback_fresh(uint32 now_ms)
{
    return ((0U != g_steer_feedback_valid) &&
            (ctrl_scan_elapsed_ms(now_ms, g_steer_feedback_update_ms) <= PID_STEER_FEEDBACK_TIMEOUT_MS)) ? 1U : 0U;
}

static uint8 ctrl_steer_scan_speed_low(void)
{
    return ((g_steer_feedback_speed_counts_s <= PID_STEER_STALL_SPEED_COUNTS_S) &&
            (g_steer_feedback_speed_counts_s >= -PID_STEER_STALL_SPEED_COUNTS_S)) ? 1U : 0U;
}

static int16 ctrl_scan_wrap_counts(int16 raw, int16 ref)
{
    int32 delta = (int32)raw - (int32)ref;

    while (delta > (CTRL_STEER_SCAN_COUNTS_PER_REV / 2 - 1))
    {
        delta -= CTRL_STEER_SCAN_COUNTS_PER_REV;
    }
    while (delta < -(CTRL_STEER_SCAN_COUNTS_PER_REV / 2))
    {
        delta += CTRL_STEER_SCAN_COUNTS_PER_REV;
    }

    return (int16)delta;
}

static int16 ctrl_scan_abs_counts(int16 counts)
{
    return (counts >= 0) ? counts : (int16)(-counts);
}

static void ctrl_steer_scan_set_phase(uint8 phase, uint32 now_ms)
{
    g_steer_scan_phase = phase;
    g_steer_scan_phase_start_ms = now_ms;
    g_steer_scan_stall_start_ms = 0U;
}

static void ctrl_steer_scan_capture_right(void)
{
    int32 span = (int32)g_steer_scan_left_raw - (int32)g_steer_scan_right_raw;
    int32 center;

    while (span < 0)
    {
        span += CTRL_STEER_SCAN_COUNTS_PER_REV;
    }
    while (span >= CTRL_STEER_SCAN_COUNTS_PER_REV)
    {
        span -= CTRL_STEER_SCAN_COUNTS_PER_REV;
    }

    center = (int32)g_steer_scan_right_raw + (span / 2);
    while (center < 0)
    {
        center += CTRL_STEER_SCAN_COUNTS_PER_REV;
    }
    while (center >= CTRL_STEER_SCAN_COUNTS_PER_REV)
    {
        center -= CTRL_STEER_SCAN_COUNTS_PER_REV;
    }

    g_steer_scan_span_counts = (int16)span;
    g_steer_scan_center_raw = (int16)center;

    if ((span < CTRL_STEER_SCAN_MIN_SPAN_COUNTS) ||
        (span > CTRL_STEER_SCAN_MAX_SPAN_COUNTS))
    {
        g_steer_scan_success = 0U;
        return;
    }

    Ctrl_SetSteerCenterRaw((int16)center);
    g_steer_scan_success = 1U;
}

static data_logger_profile_t ctrl_task_logger_profile(uint8 task_id)
{
    if ((task_id == 0U) || (task_id == 4U))
    {
        return DATA_LOGGER_PROFILE_DRIVE_DEBUG;
    }

    if (task_id == 2U)
    {
        return DATA_LOGGER_PROFILE_TASK2_INS_DEBUG;
    }

    return DATA_LOGGER_PROFILE_FULL_NAV;
}

static void ctrl_steer_scan_logger_start_new_file(void)
{
    data_logger_profile_t profile = ctrl_task_logger_profile(0U);

    if ((0U != data_logger_is_running()) &&
        (data_logger_get_task_id() == 0U) &&
        (data_logger_get_profile() == (uint8)profile) &&
        (data_logger_get_target_src() == TARGET_SRC_STEER_SCAN))
    {
        data_logger_stop();
    }

    (void)data_logger_restart_task_src(0U, profile, TARGET_SRC_STEER_SCAN);
    printf("[STEER_SCAN] logger new file state=%u file=%s\r\n",
           (unsigned)data_logger_get_state(),
           data_logger_get_filename());
}

static void ctrl_steer_scan_logger_stop_once(void)
{
    if (0U == g_steer_scan_logger_stop_requested)
    {
        g_steer_scan_logger_stop_requested = 1U;
        data_logger_stop();
        printf("[STEER_SCAN] logger stop state=%u file=%s\r\n",
               (unsigned)data_logger_get_state(),
               data_logger_get_filename());
    }
}

static uint8 ctrl_logger_matches_task_src(uint8 task_id, uint8 target_src)
{
    return ((data_logger_is_running() != 0U) &&
            (data_logger_get_task_id() == task_id) &&
            (data_logger_get_profile() == (uint8)ctrl_task_logger_profile(task_id)) &&
            (data_logger_get_target_src() == target_src)) ? 1U : 0U;
}

